var M={dir:'Preuve directe (« Soit… » / « Supposons… »)',wit:'Exhiber un témoin (« Posons… »)',ce:'Contre-exemple',neg:'Montrer que la négation est vraie',dbl:'Double inclusion',eqv:"Chaîne d'équivalences",abs:"Par l'absurde",ctp:'Par contraposée',cas:'Disjonction de cas',two:'Deux implications ⇒ et ⇐',tr:'Traduction mécanique (∀ / ∃ / négation)',rec:'Récurrence',as:'Analyse-synthèse',tab:'Table de vérité',inc:'Inclusion simple (« Soit x ∈ … »)',calc:'Deviner + prouver par double inclusion'};

var exos=[
/* ---------- CC 2023 ---------- */
{id:'23-1a',src:'CC 2023 · Ex 1.1',pts:2,k:'a',
 q:R`$f(x)=ax^2+bx+c$, $a\neq0$. $P$ : « Si $ac<0$ alors $f(x)=0$ admet deux solutions réelles distinctes. » $P$ est-elle vraie ?`,
 m:['dir','ce','rec','abs'],mw:R`On suppose l'hypothèse et on déroule : le discriminant fait tout le travail.`,
 l:[R`Supposons $ac<0$. Le discriminant vaut $\Delta=b^2-4ac$.`,R`Prenons $a=1$, $b=3$, $c=2$.`,R`Soit $x\in\mathbb R$ tel que $f(x)=0$.`],
 hint:R`Quel est le signe de $-4ac$ ? Et celui de $b^2$ ?`,
 sol:R`Supposons $ac<0$. Alors $-4ac>0$ et $b^2\ge0$, donc $\Delta=b^2-4ac>0$. Comme $a\neq0$, l'équation du second degré $f(x)=0$ admet deux solutions réelles distinctes. <b>$P$ est vraie.</b>`,
 bar:[[0.5,'« Supposons ac < 0 »'],[1,'Δ > 0 justifié (b² ≥ 0 et −4ac > 0)'],[0.5,'Conclusion « P est vraie »']]},
{id:'23-1b',src:'CC 2023 · Ex 1.2',pts:2,k:'a',
 q:R`Même $P$. Énoncer la réciproque de $P$. Est-elle vraie ?`,
 m:['ce','dir','ctp','abs'],mw:R`On énonce $Q\Rightarrow P$, puis on la tue avec un exemple où $Q$ est vraie et $P$ fausse.`,
 l:[R`La réciproque est : si $f(x)=0$ admet deux solutions réelles distinctes, alors $ac<0$.`,R`La réciproque est : si $ac\ge0$, alors $f(x)=0$ n'admet pas deux solutions distinctes.`,R`La réciproque est : $ac<0$ et $f(x)=0$ n'a pas deux solutions.`],
 lw:R`Le 2ᵉ choix est la <b>contraposée</b>, le 3ᵉ la <b>négation</b>.`,
 hint:R`Cherche un trinôme à racines « simples » ($-1$ et $-2$) avec $a$ et $c$ de même signe.`,
 sol:R`Réciproque : si $f(x)=0$ admet deux solutions réelles distinctes, alors $ac<0$.<br><b>Fausse</b> : $x^2+3x+2=(x+1)(x+2)=0$ a deux solutions distinctes $-1$ et $-2$, et pourtant $ac=2>0$.`,
 bar:[[1,'Énoncé correct de la réciproque'],[1,'Contre-exemple vérifié (racines + signe de ac)']]},
{id:'23-1c',src:'CC 2023 · Ex 1.3',pts:1,k:'a',
 q:R`Même $P$. Énoncer la contraposée de $P$.`,
 m:['tr','ctp','ce','dbl'],mw:R`On ne démontre rien : on <b>écrit</b> non $Q\Rightarrow$ non $P$.`,
 l:[R`Si $f(x)=0$ n'admet pas deux solutions réelles distinctes, alors $ac\ge0$.`,R`Si $f(x)=0$ n'admet pas deux solutions réelles distinctes, alors $ac>0$.`,R`Si $ac\ge0$, alors $f(x)=0$ n'admet pas deux solutions réelles distinctes.`],
 lw:R`non($ac<0$) c'est $ac\ge0$ (pas $>0$). Le 3ᵉ choix est l'<b>inverse</b> (non $P\Rightarrow$ non $Q$), pas la contraposée.`,
 hint:R`Nie les deux morceaux, puis inverse le sens.`,
 sol:R`Contraposée : <b>si l'équation $f(x)=0$ n'admet pas deux solutions réelles distinctes, alors $ac\ge0$.</b>`,
 bar:[[1,'Sens inversé + les deux négations correctes (≥ !)']]},
{id:'23-2a',src:'CC 2023 · Ex 2.1',pts:2,k:'a',
 q:R`$P : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ y^2\neq x$ et $Q : \exists y\in\mathbb R,\ \forall x\in\mathbb R,\ y^2\neq x$. Former les négations, puis les écrire en français sans quantificateurs.`,
 m:['tr','neg','ce','dbl'],mw:R`Négation mécanique : $\forall\leftrightarrow\exists$, ordre conservé, $\neq$ devient $=$.`,
 l:[R`$\text{non}P : \exists x\in\mathbb R,\ \forall y\in\mathbb R,\ y^2=x$`,R`$\text{non}P : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ y^2=x$`,R`$\text{non}P : \exists y\in\mathbb R,\ \forall x\in\mathbb R,\ y^2=x$`],
 lw:R`Le 3ᵉ inverse l'<b>ordre</b> des variables : interdit.`,
 hint:R`Pour la phrase : « il existe un réel qui est le carré de … ».`,
 sol:R`$\text{non}P : \exists x\in\mathbb R,\ \forall y\in\mathbb R,\ y^2=x$ : « il existe un réel qui est le carré de tous les réels ».<br>$\text{non}Q : \forall y\in\mathbb R,\ \exists x\in\mathbb R,\ y^2=x$ : « le carré de tout réel est un réel ».`,
 bar:[[0.5,'non P'],[0.5,'phrase non P'],[0.5,'non Q'],[0.5,'phrase non Q']]},
{id:'23-2b',src:'CC 2023 · Ex 2.2',pts:1.5,k:'a',
 q:R`Montrer que $P : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ y^2\neq x$ est vraie.`,
 m:['neg','tr','rec','dbl'],mw:R`Le corrigé montre que non $P$ est <b>fausse</b>. Aussi accepté : « Soit $x$ » + disjonction de cas ($x\neq0$ : $y=0$ ; $x=0$ : $y=1$).`,
 l:[R`Supposons non $P$ : $\exists x\in\mathbb R,\ \forall y\in\mathbb R,\ y^2=x$.`,R`Posons $y=0$ ; alors $y^2=0\neq x$.`,R`Soit $y\in\mathbb R$, posons $x=y^2$.`],
 lw:R`$y=0$ ne marche pas pour $x=0$ : il faut distinguer les cas ou passer par la négation.`,
 hint:R`Si un même $x$ était le carré de tous les réels, que vaudraient $1^2$ et $2^2$ ?`,
 sol:R`Supposons non $P$ : il existe $x$ tel que $\forall y,\ y^2=x$. Avec $y=1$ puis $y=2$ : $x=1$ et $x=4$, contradiction. Donc non $P$ est fausse et <b>$P$ est vraie</b>.<br><i>Variante</i> : soit $x\in\mathbb R$. Si $x\neq0$, $y=0$ convient ($0\neq x$) ; si $x=0$, $y=1$ convient.`,
 bar:[[0.5,'Bonne stratégie annoncée'],[1,'Argument (1 ≠ 4 ou disjonction de cas complète)']]},
{id:'23-2c',src:'CC 2023 · Ex 2.3',pts:1.5,k:'a',
 q:R`Montrer que $Q : \exists y\in\mathbb R,\ \forall x\in\mathbb R,\ y^2\neq x$ est fausse.`,
 m:['neg','ce','dir','abs'],mw:R`Montrer qu'un énoncé est faux revient à prouver que sa négation est vraie.`,
 l:[R`Montrons que non $Q : \forall y\in\mathbb R,\ \exists x\in\mathbb R,\ y^2=x$ est vraie. Soit $y\in\mathbb R$.`,R`Posons $y=0$. Alors $y^2\neq x$ pour tout $x$.`,R`Soit $x\in\mathbb R$. Posons $y=\sqrt x$.`],
 hint:R`Pour un $y$ donné, quel $x$ est égal à $y^2$ ?`,
 sol:R`Montrons non $Q$ : soit $y\in\mathbb R$. Posons $x=y^2\in\mathbb R$ : on a bien $y^2=x$. Donc non $Q$ est vraie, et <b>$Q$ est fausse</b>.`,
 bar:[[0.5,'Passage par la négation'],[0.5,'« Soit y », x = y²'],[0.5,'Conclusion Q fausse']]},
{id:'23-3a',src:'CC 2023 · Ex 3.1',pts:2.5,k:'a',
 q:R`$A,B,C\subset E$. Montrer que si $A\cap B=A\cap C$ alors $A\cap B^c=A\cap C^c$.`,
 m:['dbl','ce','rec','tab'],mw:R`On suppose l'hypothèse, puis égalité d'ensembles = double inclusion. Dans chaque inclusion, une petite disjonction de cas (ou absurde).`,
 l:[R`Supposons $A\cap B=A\cap C$. Montrons $A\cap B^c\subset A\cap C^c$ : soit $x\in A\cap B^c$.`,R`Soit $x\in A$. Alors $x\in B$ et $x\in C$.`,R`On a $A\cap B^c=A\cap C^c$ car $B^c=C^c$.`],
 lw:R`Rien ne dit que $B=C$ : on ne peut pas « simplifier par $A$ ».`,
 hint:R`Soit $x\in A$, $x\notin B$. Que se passerait-il si $x\in C$ ?`,
 sol:R`Supposons $A\cap B=A\cap C$. Soit $x\in A\cap B^c$ : $x\in A$ et $x\notin B$. Si $x\in C$, alors $x\in A\cap C=A\cap B$ donc $x\in B$ : impossible. Donc $x\in C^c$, et $x\in A\cap C^c$. D'où $A\cap B^c\subset A\cap C^c$.<br>Par un raisonnement analogue (en échangeant $B$ et $C$), $A\cap C^c\subset A\cap B^c$. <b>Égalité par double inclusion.</b>`,
 bar:[[0.5,'« On suppose » + annonce double inclusion'],[1.5,'Première inclusion complète'],[0.5,'Seconde inclusion (« de façon analogue » accepté)']]},
{id:'23-3b',src:'CC 2023 · Ex 3.2',pts:2.5,k:'a',
 q:R`Montrer que $A\subset B\Rightarrow A\cup C\subset B\cup C$. La réciproque est-elle vraie ?`,
 m:['inc','dbl','abs','rec'],mw:R`Sens direct : inclusion simple. Réciproque : contre-exemple.`,
 l:[R`Supposons $A\subset B$. Soit $x\in A\cup C$ : $x\in A$ ou $x\in C$.`,R`Supposons $A\subset B$. Soit $x\in A\cup C$ : $x\in A$ et $x\in C$.`,R`Supposons $A\cup C\subset B\cup C$. Soit $x\in A$.`],
 lw:R`$\cup$ se traduit par <b>ou</b>. Le 3ᵉ démarre la réciproque, pas l'implication demandée.`,
 hint:R`Réciproque : prends $C$ « gros » pour masquer la différence entre $A$ et $B$.`,
 sol:R`Supposons $A\subset B$. Soit $x\in A\cup C$. Si $x\in A$, alors $x\in B$ (hypothèse) ; sinon $x\in C$. Donc $x\in B$ ou $x\in C$, i.e. $x\in B\cup C$.<br>Réciproque : $A\cup C\subset B\cup C\Rightarrow A\subset B$. <b>Fausse</b> : $A=\{1\}$, $B=\emptyset$, $C=\{1\}$ : $A\cup C=\{1\}\subset B\cup C=\{1\}$ mais $A\not\subset B$.`,
 bar:[[1.5,'Implication (on suppose, soit x, deux cas)'],[0.5,'Énoncé de la réciproque'],[0.5,'Contre-exemple vérifié']]},
{id:'23-4a',src:'CC 2023 · Ex 4.1',pts:2,k:'a',
 q:R`$A\subset\mathbb R^2$, $P_1(A)=\{x\in\mathbb R:\exists y\in\mathbb R,(x,y)\in A\}$, $P_2(A)=\{y\in\mathbb R:\exists x\in\mathbb R,(x,y)\in A\}$. Montrer $A\subset P_1(A)\times P_2(A)$.`,
 m:['inc','dbl','abs','wit'],mw:R`Une seule inclusion : on prend un couple de $A$.`,
 l:[R`Soit $(x,y)\in A$.`,R`Soit $x\in P_1(A)$.`,R`Montrons l'égalité par double inclusion.`],
 lw:R`L'élément de $A$ est un <b>couple</b>. Et on ne demande pas d'égalité.`,
 hint:R`Pour avoir $x\in P_1(A)$, il faut un $y$ tel que $(x,y)\in A$ : tu l'as déjà sous la main !`,
 sol:R`Soit $(x,y)\in A$. Alors $x\in\mathbb R$ et il existe un réel (à savoir $y$) tel que $(x,y)\in A$ : donc $x\in P_1(A)$. De même $y\in\mathbb R$ et il existe $x$ tel que $(x,y)\in A$ : $y\in P_2(A)$. Par définition du produit cartésien, $(x,y)\in P_1(A)\times P_2(A)$. Comme $(x,y)$ est quelconque, l'inclusion est démontrée.`,
 bar:[[0.5,'Soit (x, y) ∈ A'],[1,'x ∈ P₁(A) et y ∈ P₂(A) justifiés par le ∃'],[0.5,'Conclusion produit cartésien']]},
{id:'23-4b',src:'CC 2023 · Ex 4.2',pts:3,k:'a',
 q:R`$C,D$ parties <b>non vides</b> de $\mathbb R$. Déterminer $P_1(C\times D)$ et $P_2(C\times D)$.`,
 m:['calc','inc','ce','rec'],mw:R`On devine $P_1(C\times D)=C$ puis double inclusion. Le « non vide » sert dans $C\subset P_1$.`,
 l:[R`Montrons $P_1(C\times D)=C$ par double inclusion. Soit $x\in P_1(C\times D)$.`,R`$P_1(C\times D)=C\times D$.`,R`Soit $x\in C$. Alors $(x,x)\in C\times D$.`],
 lw:R`$(x,x)$ n'a aucune raison d'être dans $C\times D$ : il faut un $y\in D$.`,
 hint:R`Pour $C\subset P_1(C\times D)$ : où trouver un $y$ tel que $(x,y)\in C\times D$ ?`,
 sol:R`<b>$P_1(C\times D)=C$</b>. ($\subset$) Soit $x\in P_1(C\times D)$ : $\exists y$, $(x,y)\in C\times D$, donc $x\in C$. ($\supset$) Soit $x\in C$. <b>$D$ étant non vide</b>, il existe $y\in D$ ; alors $(x,y)\in C\times D$ et $x\in P_1(C\times D)$. Égalité par double inclusion.<br>De façon analogue (avec $C\neq\emptyset$), <b>$P_2(C\times D)=D$</b>.`,
 bar:[[0.5,'Bon résultat annoncé'],[0.75,'Inclusion ⊂'],[1,'Inclusion ⊃ avec « D non vide »'],[0.75,'P₂ par analogie']]},
/* ---------- CC 2024 ---------- */
{id:'24-1a',src:'CC 2024 · Ex 1 (A)',pts:1.25,k:'a',
 q:R`$A : \exists x\in\mathbb R,\ \forall y\in\mathbb R,\ x+y>0$. Nier $A$, puis dire si $A$ est vraie ou fausse.`,
 m:['neg','wit','rec','dbl'],mw:R`$A$ est fausse (aucun $x$ ne résiste à $y$ très négatif) : on prouve non $A$.`,
 l:[R`$\text{non}A : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ x+y\le0$. Soit $x\in\mathbb R$, posons $y=-x-1$.`,R`$\text{non}A : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ x+y<0$. Soit $x$, posons $y=-x-1$.`,R`Posons $x=1$. Soit $y\in\mathbb R$, alors $x+y>0$.`],
 lw:R`non($>$) c'est $\le$. Et $x=1$ échoue pour $y=-5$.`,
 hint:R`Pour un $x$ donné, quel $y$ rend $x+y$ négatif ?`,
 sol:R`$\text{non}A : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ x+y\le0$. Elle est vraie : soit $x\in\mathbb R$, posons $y=-x-1$ ; alors $x+y=-1\le0$. Donc <b>$A$ est fausse</b>.`,
 bar:[[0.5,'Négation (≤ !)'],[0.75,'Témoin y = −x − 1 + conclusion']]},
{id:'24-1b',src:'CC 2024 · Ex 1 (B)',pts:1.25,k:'a',
 q:R`$B : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ x+y>0$. Nier $B$, puis dire si $B$ est vraie ou fausse.`,
 m:['wit','ce','neg','abs'],mw:R`« Soit $x$ », puis on construit $y$ qui dépend de $x$.`,
 l:[R`Soit $x\in\mathbb R$. Posons $y=-x+1$.`,R`Posons $y=1$. Soit $x\in\mathbb R$.`,R`Soit $x\in\mathbb R$ et soit $y\in\mathbb R$.`],
 lw:R`$y=1$ fixé ne marche pas pour $x=-5$ : $y$ doit dépendre de $x$. Et « soit $y$ » rate le $\exists$.`,
 hint:R`Il suffit que $x+y$ vaille $1$.`,
 sol:R`$\text{non}B : \exists x\in\mathbb R,\ \forall y\in\mathbb R,\ x+y\le0$.<br>$B$ est <b>vraie</b> : soit $x\in\mathbb R$, posons $y=-x+1$ ; alors $x+y=1>0$.`,
 bar:[[0.5,'Négation'],[0.75,'Soit x, y = −x + 1, vérification']]},
{id:'24-1c',src:'CC 2024 · Ex 1 (C)',pts:1.25,k:'a',
 q:R`$C : \forall x\in\mathbb R,\ \forall y\in\mathbb R,\ x+y>0$. Nier $C$, puis dire si $C$ est vraie ou fausse.`,
 m:['ce','dir','wit','rec'],mw:R`Un $\forall\forall$ faux : un seul couple contre-exemple.`,
 l:[R`Contre-exemple : $x=-1$, $y=0$ donne $x+y=-1\le0$.`,R`Soit $(x,y)\in\mathbb R^2$. Alors $x+y>0$.`,R`$\text{non}C : \forall x,\ \forall y,\ x+y\le0$.`],
 lw:R`La négation de $\forall\forall$ est $\exists\exists$.`,
 hint:R`Deux nombres négatifs (ou nuls)…`,
 sol:R`$\text{non}C : \exists x\in\mathbb R,\ \exists y\in\mathbb R,\ x+y\le0$. Vraie avec $x=-1$, $y=0$. Donc <b>$C$ est fausse</b>.`,
 bar:[[0.5,'Négation ∃∃'],[0.75,'Contre-exemple']]},
{id:'24-1d',src:'CC 2024 · Ex 1 (D)',pts:1.25,k:'a',
 q:R`$D : \exists x\in\mathbb R,\ \forall y\in\mathbb R,\ y^2>x$. Nier $D$, puis dire si $D$ est vraie ou fausse.`,
 m:['wit','neg','ce','rec'],mw:R`$\exists x\,\forall y$ : on fixe un $x$ <b>numérique</b>, puis « soit $y$ ».`,
 l:[R`Posons $x=-1$. Soit $y\in\mathbb R$ : $y^2\ge0>-1$.`,R`Soit $y\in\mathbb R$. Posons $x=y^2-1$.`,R`Posons $x=0$. Soit $y\in\mathbb R$ : $y^2>0$.`],
 lw:R`Le 2ᵉ fait dépendre $x$ de $y$ (interdit). Le 3ᵉ rate $y=0$ ($0>0$ est faux).`,
 hint:R`Un carré est toujours $\ge0$…`,
 sol:R`$\text{non}D : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ y^2\le x$.<br>$D$ est <b>vraie</b> : posons $x=-1$ ; pour tout $y\in\mathbb R$, $y^2\ge0>-1=x$.`,
 bar:[[0.5,'Négation'],[0.75,'x = −1 fixé, vérification pour tout y']]},
{id:'24-2a',src:'CC 2024 · Ex 2.1 (a, b)',pts:2,k:'a',
 q:R`$f(x)=x^2-1$ sur $E$. Assertion : « $\forall(a,b)\in E^2$, si $f(a)=f(b)$ alors $a=b$ ». Écrire sa négation. Est-elle vraie si $E=\mathbb R$ ?`,
 m:['ce','dir','ctp','rec'],mw:R`Négation d'un $\forall(\dots\Rightarrow\dots)$ : $\exists(\dots$ et non $\dots)$. Pour $E=\mathbb R$ : contre-exemple.`,
 l:[R`$\exists(a,b)\in E^2,\ f(a)=f(b)$ et $a\neq b$.`,R`$\exists(a,b)\in E^2,\ f(a)=f(b)\Rightarrow a\neq b$.`,R`$\exists(a,b)\in E^2,\ f(a)\neq f(b)$ et $a\neq b$.`],
 lw:R`non($P\Rightarrow Q$) = $P$ <b>et</b> non $Q$ : on garde $f(a)=f(b)$.`,
 hint:R`$x^2$ ne voit pas le signe de $x$.`,
 sol:R`Négation : $\exists(a,b)\in E^2,\ f(a)=f(b)$ <b>et</b> $a\neq b$.<br>Si $E=\mathbb R$ : $f(-1)=f(1)=0$ et $-1\neq1$. La négation est vraie, donc <b>l'assertion est fausse</b>.`,
 bar:[[1,'Négation (∃, « et », a ≠ b)'],[1,'Contre-exemple f(−1) = f(1)']]},
{id:'24-2c',src:'CC 2024 · Ex 2.1 (c)',pts:1.5,k:'a',
 q:R`$f(x)=x^2-1$. Si $E=[1,+\infty[$, l'assertion « $\forall(a,b)\in E^2$, $f(a)=f(b)\Rightarrow a=b$ » est-elle vraie ?`,
 m:['dir','ce','wit','neg'],mw:R`Vraie : soit $(a,b)$, on suppose $f(a)=f(b)$ et on arrive à $a=b$.`,
 l:[R`Soit $(a,b)\in[1,+\infty[^2$. Supposons $f(a)=f(b)$.`,R`Prenons $a=1$ et $b=1$ : $f(a)=f(b)$ et $a=b$.`,R`Supposons $a=b$. Alors $f(a)=f(b)$.`],
 lw:R`Un exemple ne prouve pas un $\forall$. Le 3ᵉ démontre la <b>réciproque</b>.`,
 hint:R`$a^2=b^2\Rightarrow a=b$ n'est vrai que sous une condition de signe.`,
 sol:R`Soit $(a,b)\in[1,+\infty[^2$ avec $f(a)=f(b)$. Alors $a^2-1=b^2-1$, donc $a^2=b^2$, donc $|a|=|b|$, et <b>comme $a>0$ et $b>0$</b>, $a=b$. L'assertion est <b>vraie</b>.`,
 bar:[[0.5,'Soit (a, b), supposons f(a) = f(b)'],[0.5,'a² = b²'],[0.5,'a = b « car a, b > 0 »']]},
{id:'24-2d',src:'CC 2024 · Ex 2.2 (a)',pts:1,k:'a',
 q:R`$f(x)=x^2-1$, $E=F=\mathbb R$. « $\forall y\in F,\ \exists x\in E,\ y=f(x)$ » est-elle vraie ?`,
 m:['ce','wit','dir','rec'],mw:R`Un $y$ sans antécédent suffit : $f(x)\ge-1$ toujours.`,
 l:[R`Prenons $y=-2$ : $y=f(x)\iff x^2=-1$, impossible.`,R`Soit $y\in\mathbb R$, posons $x=\sqrt{y+1}$.`,R`Prenons $y=0$ : $x=1$ convient.`],
 lw:R`$\sqrt{y+1}$ n'existe pas si $y<-1$. Un exemple qui marche ne prouve rien ici.`,
 hint:R`Quelle est la plus petite valeur de $x^2-1$ ?`,
 sol:R`<b>Fausse</b> : pour $y=-2$, $y=f(x)\iff x^2=-1$, impossible dans $\mathbb R$. Il n'existe donc pas de $x$.`,
 bar:[[1,'y = −2 (ou tout y < −1) + justification']]},
{id:'24-2e',src:'CC 2024 · Ex 2.2 (b)',pts:1.5,k:'a',
 q:R`$f(x)=x^2-1$, $F=[0,+\infty[$, $E=[1,+\infty[$. « $\forall y\in F,\ \exists x\in E,\ y=f(x)$ » est-elle vraie ?`,
 m:['wit','ce','abs','rec'],mw:R`Soit $y$, on résout l'équation, on pose $x$ et on <b>vérifie $x\in E$</b>.`,
 l:[R`Soit $y\in[0,+\infty[$. On cherche $x\ge1$ tel que $x^2-1=y$, soit $x^2=y+1$.`,R`Soit $x\in[1,+\infty[$. Posons $y=x^2-1$.`,R`Posons $x=1$ : $f(1)=0\in F$.`],
 lw:R`Ici on part de $y$ (le $\forall$ porte sur $y$).`,
 hint:R`$x=\sqrt{y+1}$ : pourquoi est-il $\ge1$ ?`,
 sol:R`Soit $y\in[0,+\infty[$. $y=x^2-1\iff x^2=y+1$. Posons $x=\sqrt{y+1}$ : comme $y\ge0$, $y+1\ge1$ donc $x\ge1$, i.e. $x\in E$, et $f(x)=y$. L'assertion est <b>vraie</b>.`,
 bar:[[0.5,'Soit y + résolution'],[0.5,'x = √(y+1)'],[0.5,'x ∈ E vérifié (x ≥ 1)']]},
{id:'24-3a',src:'CC 2024 · Ex 3.1',pts:1,k:'a',
 q:R`$A,B\subset E$. Montrer que si $A\cap B=\emptyset$ alors $B\subset C_E(A)$.`,
 m:['inc','dbl','ce','rec'],mw:R`On suppose l'hypothèse, puis inclusion simple.`,
 l:[R`On suppose $A\cap B=\emptyset$. Soit $x\in B$.`,R`Soit $x\in C_E(A)$.`,R`On suppose $A\cap B=\emptyset$. Soit $x\in A$.`],
 hint:R`Si $x\in B$ était aussi dans $A$…`,
 sol:R`On suppose $A\cap B=\emptyset$. Soit $x\in B$. Alors $x\notin A$ (sinon $x\in A\cap B=\emptyset$), donc $x\in C_E(A)$. Puisque c'est vrai pour tout $x\in B$, $B\subset C_E(A)$.`,
 bar:[[0.25,'On suppose + soit x ∈ B'],[0.5,'x ∉ A car A ∩ B = ∅'],[0.25,'Conclusion']]},
{id:'24-3b',src:'CC 2024 · Ex 3.2',pts:1,k:'a',
 q:R`Montrer que si $C_E(A)\cap C_E(B)=\emptyset$ alors $C_E(A)\subset B$.`,
 m:['inc','abs','ce','tab'],mw:R`Même moule que 3.1, avec $C_E(C_E(B))=B$.`,
 l:[R`On suppose $C_E(A)\cap C_E(B)=\emptyset$. Soit $x\in C_E(A)$.`,R`Soit $x\in B$.`,R`On suppose $C_E(A)\cap C_E(B)=\emptyset$, donc $A\cap B=\emptyset$.`],
 lw:R`Le 3ᵉ est faux : $C_E(A)\cap C_E(B)=C_E(A\cup B)$, ça ne donne pas $A\cap B=\emptyset$.`,
 hint:R`Copie la 3.1 en remplaçant $A$ par $C_E(A)$ et $B$ par $C_E(B)$.`,
 sol:R`On suppose $C_E(A)\cap C_E(B)=\emptyset$. Soit $x\in C_E(A)$. Alors $x\notin C_E(B)$, donc $x\in C_E(C_E(B))=B$. Puisque c'est vrai pour tout $x\in C_E(A)$, $C_E(A)\subset B$.`,
 bar:[[0.25,'On suppose + soit x'],[0.5,'x ∉ C_E(B) donc x ∈ B'],[0.25,'Conclusion']]},
{id:'24-3c',src:'CC 2024 · Ex 3.3',pts:2,k:'a',
 q:R`Montrer : $\big(A\cap B=\emptyset$ et $C_E(A)\cap C_E(B)=\emptyset\big)\iff B=C_E(A)$.`,
 m:['two','eqv','abs','ce'],mw:R`Deux sens. Le $\Rightarrow$ est gratuit grâce aux questions 1 et 2 !`,
 l:[R`$(\Rightarrow)$ D'après 1) et 2), $B\subset C_E(A)$ et $C_E(A)\subset B$, donc $B=C_E(A)$.`,R`Soit $x\in B$. Alors $x\in C_E(A)$.`,R`$(\Rightarrow)$ Supposons $B=C_E(A)$.`],
 lw:R`Le 3ᵉ attaque en fait le sens $\Leftarrow$.`,
 hint:R`Réciproque : remplace $B$ par $C_E(A)$ dans les deux intersections.`,
 sol:R`$(\Rightarrow)$ D'après 1) et 2) : $B\subset C_E(A)$ et $C_E(A)\subset B$, donc $B=C_E(A)$.<br>$(\Leftarrow)$ Réciproquement, si $B=C_E(A)$ : $A\cap B=A\cap C_E(A)=\emptyset$ et $C_E(A)\cap C_E(B)=C_E(A)\cap C_E(C_E(A))=C_E(A)\cap A=\emptyset$.`,
 bar:[[1,'Sens ⇒ via 1) et 2)'],[1,'Réciproque (1 pt dans le corrigé)']]},
{id:'24-4a',src:'CC 2024 · Ex 4.1',pts:1.5,k:'a',
 q:R`$B_n=\{-n,n\}$ pour $n\in\mathbb N^*$. Montrer $\bigcup_{n\in\mathbb N^*}B_n\subset\mathbb Z$. A-t-on l'égalité ?`,
 m:['inc','dbl','rec','abs'],mw:R`Inclusion simple, puis contre-exemple pour l'égalité.`,
 l:[R`Soit $x\in\bigcup_{n\in\mathbb N^*}B_n$ : il existe $n\in\mathbb N^*$ tel que $x\in B_n$.`,R`Soit $x\in\bigcup B_n$ : pour tout $n$, $x\in B_n$.`,R`Soit $x\in\mathbb Z$. Alors $x\in B_x$.`],
 lw:R`Union = <b>il existe</b> $n$.`,
 hint:R`Quel entier n'est jamais égal à $\pm n$ avec $n\ge1$ ?`,
 sol:R`Soit $x\in\bigcup B_n$ : $\exists n\in\mathbb N^*$, $x\in B_n=\{-n,n\}\subset\mathbb Z$, donc $x\in\mathbb Z$. Inclusion OK.<br><b>Pas d'égalité</b> : $0\in\mathbb Z$ mais $0\notin\bigcup B_n$ (car $n\ge1$ donc $\pm n\neq0$).`,
 bar:[[1,'Inclusion (∃ n)'],[0.5,'0 ∉ union']]},
{id:'24-4b',src:'CC 2024 · Ex 4.2',pts:1.5,k:'a',
 q:R`$A_n=]-n,n[$. Déterminer $A_1\setminus A_2$ et $A_2\setminus A_1$.`,
 m:['eqv','rec','ce','wit'],mw:R`On traduit $x\in A\setminus B$ en inégalités et on simplifie par équivalences.`,
 l:[R`$x\in A_2\setminus A_1\iff -2<x<2$ et $(x\le-1$ ou $x\ge1)$`,R`$x\in A_2\setminus A_1\iff -2<x<2$ et $-1<x<1$`,R`$A_2\setminus A_1=]-2,2[\,\setminus\,]-1,1[\,=\,]-1,1[$`],
 lw:R`$x\notin\,]-1,1[$ se traduit par $x\le-1$ <b>ou</b> $x\ge1$.`,
 hint:R`$A_1\subset A_2$ : que vaut alors $A_1\setminus A_2$ ?`,
 sol:R`$A_1\subset A_2$ donc <b>$A_1\setminus A_2=\emptyset$</b>.<br>$x\in A_2\setminus A_1\iff -2<x<2$ et ($x\le-1$ ou $x\ge1$) $\iff(-2<x\le-1)$ ou $(1\le x<2)$. Donc <b>$A_2\setminus A_1=]-2,-1]\cup[1,2[$</b>.<br><i>Le corrigé imprimé écrit « $\cap$ » : c'est une coquille, c'est bien $\cup$.</i>`,
 bar:[[0.5,'A₁ \\ A₂ = ∅'],[1,'A₂ \\ A₁ = ]−2,−1] ∪ [1,2[ justifié']]},
{id:'24-4c',src:'CC 2024 · Ex 4.3',pts:2,k:'a',
 q:R`$A_n=]-n,n[$, $n\in\mathbb N^*$. Déterminer $\bigcap_{n\in\mathbb N^*}A_n$ et $\bigcup_{n\in\mathbb N^*}A_n$.`,
 m:['calc','rec','ce','abs'],mw:R`Famille croissante : $\bigcap=A_1$ et $\bigcup=\mathbb R$, prouvé par double inclusion.`,
 l:[R`On remarque que $A_n\subset A_{n+1}$ pour tout $n$, donc $\bigcap A_n=A_1$.`,R`$\bigcap A_n=\emptyset$ car les intervalles grandissent.`,R`$\bigcup A_n=\,]-\infty,+\infty[$ car $n\to+\infty$.`],
 lw:R`« Car $n\to+\infty$ » ne vaut aucun point : il faut un $n$ explicite.`,
 hint:R`Pour $x\in\mathbb R$, quel $n\in\mathbb N^*$ vérifie $|x|<n$ ? Pense à $E(|x|)$.`,
 sol:R`Les $A_n$ sont emboîtés ($A_n\subset A_{n+1}$) donc <b>$\bigcap A_n=A_1=]-1,1[$</b>.<br><b>$\bigcup A_n=\mathbb R$</b> : ($\subset$) chaque $A_n\subset\mathbb R$. ($\supset$) Soit $x\in\mathbb R$ ; posons $n=E(|x|)+1\in\mathbb N^*$. Alors $|x|<n$, donc $x\in\,]-n,n[\,=A_n\subset\bigcup A_n$.`,
 bar:[[0.75,'Intersection = A₁ (emboîtement)'],[0.5,'Union ⊂ ℝ'],[0.75,'ℝ ⊂ union avec n explicite']]},
/* ---------- CC 2025 ---------- */
{id:'25-1a',src:'CC 2025 · Ex 1.1',pts:1.5,k:'a',
 q:R`$\mathcal P$ = ensemble des nombres premiers. Écrire avec quantificateurs, puis nier : « Tout entier pair strictement supérieur à 2 est la somme de deux nombres premiers. »`,
 m:['tr','neg','rec','wit'],mw:R`Traduction pure. « Tout » donne $\forall$, la condition « pair et $>2$ » se met en implication (ou dans l'ensemble).`,
 l:[R`$\forall n\in\mathbb N,\ (n\text{ pair et }n>2)\Rightarrow\exists(p,q)\in\mathcal P^2,\ n=p+q$`,R`$\exists(p,q)\in\mathcal P^2,\ \forall n\in 2\mathbb N,\ n=p+q$`,R`$\forall n\in2\mathbb N,\ \forall(p,q)\in\mathcal P^2,\ n=p+q$`],
 lw:R`$p,q$ dépendent de $n$ : le $\exists$ vient <b>après</b> le $\forall n$.`,
 hint:R`Négation : $\forall(A\Rightarrow B)$ devient $\exists(A$ et non $B)$.`,
 sol:R`$\forall n\in2\mathbb N,\ n>2\Rightarrow\exists(p,q)\in\mathcal P^2,\ n=p+q$.<br>Négation : $\exists n\in2\mathbb N,\ n>2$ <b>et</b> $\forall(p,q)\in\mathcal P^2,\ n\neq p+q$.`,
 bar:[[0.75,'Écriture quantifiée'],[0.75,'Négation']]},
{id:'25-1b',src:'CC 2025 · Ex 1.2',pts:1.5,k:'a',
 q:R`Écrire avec quantificateurs, puis nier : « Tout nombre premier de la forme $4n+1$ est la somme des carrés de deux entiers naturels. »`,
 m:['tr','neg','wit','ce'],mw:R`Même moule : $\forall n$, condition « $4n+1\in\mathcal P$ » en implication, puis $\exists(k,l)$.`,
 l:[R`$\forall n\in\mathbb N,\ 4n+1\in\mathcal P\Rightarrow\exists(k,l)\in\mathbb N^2,\ 4n+1=k^2+l^2$`,R`$\forall n\in\mathbb N,\ \exists(k,l)\in\mathbb N^2,\ 4n+1=k^2+l^2$`,R`$\exists(k,l)\in\mathbb N^2,\ \forall n\in\mathbb N,\ 4n+1\in\mathcal P\Rightarrow 4n+1=k^2+l^2$`],
 lw:R`Le 2ᵉ oublie « premier ». Le 3ᵉ fixe $k,l$ pour tous les $n$.`,
 hint:R`Négation : il existe un tel premier qui n'est somme d'aucun couple de carrés.`,
 sol:R`$\forall n\in\mathbb N,\ 4n+1\in\mathcal P\Rightarrow\exists(k,l)\in\mathbb N^2,\ 4n+1=k^2+l^2$.<br>Négation : $\exists n\in\mathbb N,\ 4n+1\in\mathcal P$ <b>et</b> $\forall(k,l)\in\mathbb N^2,\ 4n+1\neq k^2+l^2$.`,
 bar:[[0.75,'Écriture quantifiée'],[0.75,'Négation']]},
{id:'25-1c',src:'CC 2025 · Ex 1.3',pts:1.5,k:'a',
 q:R`Écrire avec quantificateurs, puis nier : « Pour tout entier $n\ge2$, il existe toujours un nombre premier strictement compris entre $n$ et $2n$. »`,
 m:['tr','neg','ce','rec'],mw:R`Traduction ; attention à la négation de l'encadrement strict.`,
 l:[R`$\forall n\in[\![2,+\infty[\![,\ \exists p\in\mathcal P,\ n<p<2n$`,R`$\exists p\in\mathcal P,\ \forall n\ge2,\ n<p<2n$`,R`$\forall n\ge2,\ \exists p\in\mathcal P,\ n\le p\le2n$`],
 lw:R`« Strictement » donne $<$. Et $p$ dépend de $n$.`,
 hint:R`non$(n<p<2n)$ = non($n<p$ et $p<2n$) = …`,
 sol:R`$\forall n\in[\![2,+\infty[\![,\ \exists p\in\mathcal P,\ n<p<2n$.<br>Négation : $\exists n\in[\![2,+\infty[\![,\ \forall p\in\mathcal P,\ p\le n$ <b>ou</b> $p\ge2n$.`,
 bar:[[0.75,'Écriture quantifiée'],[0.75,'Négation (≤ ou ≥)']]},
{id:'25-2a',src:'CC 2025 · Ex 2.1-2.2',pts:2,k:'a',
 q:R`$a\in\mathbb R$. $P$ : « Si $a$ est non nul, il existe un réel $\varepsilon>0$ tel que $|a|\ge\varepsilon$. » Écrire $P$ avec quantificateurs et montrer que $P$ est vraie.`,
 m:['wit','ce','rec','abs'],mw:R`Implication dont la conclusion est un $\exists$ : on suppose $a\neq0$ et on <b>pose</b> $\varepsilon$.`,
 l:[R`$P : a\neq0\Rightarrow\exists\varepsilon\in\mathbb R_+^*,\ |a|\ge\varepsilon$. Supposons $a\neq0$ et posons $\varepsilon=\frac{|a|}2$.`,R`$P : \forall\varepsilon>0,\ a\neq0\Rightarrow|a|\ge\varepsilon$. Soit $\varepsilon>0$.`,R`$P : a\neq0\Rightarrow\exists\varepsilon>0,\ |a|\ge\varepsilon$. Posons $\varepsilon=1$.`],
 lw:R`$\varepsilon=1$ échoue si $a=0{,}1$. $\varepsilon$ doit dépendre de $a$.`,
 hint:R`Pourquoi $\varepsilon=|a|/2$ est-il bien $>0$ ?`,
 sol:R`$P : a\neq0\Rightarrow\exists\varepsilon\in\mathbb R_+^*,\ |a|\ge\varepsilon$.<br>Supposons $a\neq0$. Posons $\varepsilon=\frac{|a|}2$ : $\varepsilon>0$ car $a\neq0$, et $|a|=2\varepsilon\ge\varepsilon$. <b>$P$ est vraie.</b> ($\varepsilon=|a|$ marche aussi.)`,
 bar:[[1,'Écriture quantifiée'],[1,'Supposons a ≠ 0, ε explicite, ε > 0 justifié']]},
{id:'25-2b',src:'CC 2025 · Ex 2.3-2.4',pts:1.5,k:'a',
 q:R`Même $P : a\neq0\Rightarrow\exists\varepsilon>0,\ |a|\ge\varepsilon$. Écrire la contraposée puis la négation de $P$.`,
 m:['tr','ctp','ce','abs'],mw:R`Pure écriture : contraposée non $Q\Rightarrow$ non $P$, négation $P$ et non $Q$.`,
 l:[R`Contraposée : $\big(\forall\varepsilon>0,\ |a|<\varepsilon\big)\Rightarrow a=0$`,R`Contraposée : $a=0\Rightarrow\forall\varepsilon>0,\ |a|<\varepsilon$`,R`Contraposée : $a\neq0$ et $\forall\varepsilon>0,\ |a|<\varepsilon$`],
 lw:R`Le 2ᵉ est l'<b>inverse</b> (non $P\Rightarrow$ non $Q$), le 3ᵉ est la <b>négation</b>.`,
 hint:R`non$(\exists\varepsilon>0,\ |a|\ge\varepsilon)$ = $\forall\varepsilon>0,\ |a|<\varepsilon$.`,
 sol:R`Contraposée : $\big(\forall\varepsilon\in\mathbb R_+^*,\ |a|<\varepsilon\big)\Rightarrow a=0$.<br>Négation : $a\neq0$ <b>et</b> $\forall\varepsilon\in\mathbb R_+^*,\ |a|<\varepsilon$.`,
 bar:[[0.75,'Contraposée'],[0.75,'Négation']]},
{id:'25-3a',src:'CC 2025 · Ex 3.1',pts:2.5,k:'a',
 q:R`$C\cap D=\emptyset$, $A\subset C$, $B\subset D$. Montrer : $A\cup B=C\cup D\Rightarrow\big(C\setminus A=\emptyset$ et $D\setminus B=\emptyset\big)$.`,
 m:['abs','ce','rec','eqv'],mw:R`Montrer qu'un ensemble est vide : par l'absurde, on suppose qu'il a un élément.`,
 l:[R`Supposons $A\cup B=C\cup D$. Par l'absurde, supposons $C\setminus A\neq\emptyset$ : soit $x\in C\setminus A$.`,R`Supposons $A\cup B=C\cup D$. Soit $x\in C\setminus A$ : $x\in C$ et $x\in A$.`,R`Supposons $C\setminus A=\emptyset$. Alors $C\subset A$.`],
 lw:R`$x\in C\setminus A$ veut dire $x\notin A$. Le 3ᵉ suppose la conclusion.`,
 hint:R`$x\in C\subset C\cup D=A\cup B$ et $x\notin A$ : donc $x\in$ ? Puis utilise $B\subset D$.`,
 sol:R`Supposons $A\cup B=C\cup D$ et, par l'absurde, $C\setminus A\neq\emptyset$ : soit $x\in C$, $x\notin A$. Comme $C\subset C\cup D=A\cup B$, $x\in A$ ou $x\in B$ ; or $x\notin A$, donc $x\in B\subset D$. Ainsi $x\in C\cap D=\emptyset$ : <b>absurde</b>. Donc $C\setminus A=\emptyset$.<br>De même (en échangeant les rôles) $D\setminus B=\emptyset$.`,
 bar:[[0.5,'Hypothèse + annonce absurde'],[1.25,'Chaîne x ∈ A ∪ B, x ∈ B ⊂ D, x ∈ C ∩ D'],[0.75,'Second cas (analogue)']]},
{id:'25-3b',src:'CC 2025 · Ex 3.2',pts:3,k:'a',
 q:R`Montrer $A\times(C\cup D)=(A\times C)\cup(A\times D)$ et $A\times(C\cap D)=(A\times C)\cap(A\times D)$.`,
 m:['eqv','abs','ce','rec'],mw:R`Chaîne d'équivalences sur $(x,y)$ : le plus rapide. Double inclusion accepté aussi.`,
 l:[R`$(x,y)\in A\times(C\cup D)\iff x\in A$ et $(y\in C$ ou $y\in D)$`,R`$A\times(C\cup D)=A\times C\cup D$ par distributivité.`,R`Soit $x\in A$ et $y\in C$.`],
 hint:R`« et » se distribue sur « ou » : $P$ et $(Q$ ou $R)\iff(P$ et $Q)$ ou $(P$ et $R)$.`,
 sol:R`$(x,y)\in A\times(C\cup D)\iff x\in A$ et ($y\in C$ ou $y\in D$) $\iff$ ($x\in A$ et $y\in C$) ou ($x\in A$ et $y\in D$) $\iff(x,y)\in A\times C$ ou $(x,y)\in A\times D\iff(x,y)\in(A\times C)\cup(A\times D)$.<br>Même chaîne avec « et » : $(x,y)\in A\times(C\cap D)\iff x\in A$ et $y\in C$ et $y\in D\iff(x,y)\in A\times C$ et $(x,y)\in A\times D$.`,
 bar:[[1.5,'Égalité avec ∪'],[1.5,'Égalité avec ∩']]},
{id:'25-4a',src:'CC 2025 · Ex 4.1',pts:1,k:'a',
 q:R`Montrer que si $\forall k\in\mathbb N,\ A_k\subset B_k$, alors $\bigcup_{k\in\mathbb N}A_k\subset\bigcup_{k\in\mathbb N}B_k$.`,
 m:['inc','dbl','rec','abs'],mw:R`Inclusion simple + définition de l'union ($\exists k$).`,
 l:[R`Soit $x\in\bigcup_k A_k$ : il existe $k\in\mathbb N$ tel que $x\in A_k$.`,R`Par récurrence sur $k$ : $A_0\subset B_0$…`,R`Soit $x\in\bigcup_k A_k$ : pour tout $k$, $x\in A_k$.`],
 hint:R`Le même $k$ marche pour $B_k$.`,
 sol:R`Soit $x\in\bigcup A_k$ : $\exists k\in\mathbb N$, $x\in A_k$. Or $A_k\subset B_k$, donc $x\in B_k$, soit $x\in\bigcup B_k$. Comme $x$ est quelconque, l'inclusion est démontrée.`,
 bar:[[0.5,'∃ k, x ∈ A_k'],[0.5,'x ∈ B_k donc dans l\'union']]},
{id:'25-4b',src:'CC 2025 · Ex 4.2',pts:1.5,k:'a',
 q:R`Montrer $\bigcup_{k\in\mathbb N}(A_k\cap B_k)\subset\big(\bigcup_k A_k\big)\cap\big(\bigcup_k B_k\big)$.`,
 m:['inc','dbl','abs','ce'],mw:R`Une seule inclusion : soit $x$ à gauche.`,
 l:[R`Soit $x\in\bigcup_k(A_k\cap B_k)$ : $\exists k$, $x\in A_k$ et $x\in B_k$.`,R`Soit $x\in\big(\bigcup A_k\big)\cap\big(\bigcup B_k\big)$.`,R`Montrons l'égalité par double inclusion.`],
 lw:R`Le 2ᵉ attaque l'inclusion réciproque (qui est fausse en général !).`,
 hint:R`Le même $k$ sert de témoin pour les deux unions.`,
 sol:R`Soit $x\in\bigcup(A_k\cap B_k)$ : $\exists k$, $x\in A_k$ et $x\in B_k$. Donc ($\exists k$, $x\in A_k$) et ($\exists k$, $x\in B_k$), i.e. $x\in\bigcup A_k$ et $x\in\bigcup B_k$. Comme $x$ est quelconque, l'inclusion est démontrée.`,
 bar:[[0.5,'Soit x, ∃ k'],[1,'Appartenance aux deux unions + conclusion']]},
{id:'25-4c',src:'CC 2025 · Ex 4.3',pts:2.5,k:'a',
 q:R`$A_k=[k-1,k]$, $B_k=[k,k+1]$, $k\in\mathbb N$. Calculer $A_k\cap B_k$, $\bigcup_k(A_k\cap B_k)$ et $\big(\bigcup_kA_k\big)\cap\big(\bigcup_kB_k\big)$.`,
 m:['calc','rec','ce','abs'],mw:R`On devine ($\{k\}$, $\mathbb N$, $[0,+\infty[$) puis on prouve par double inclusion, avec la partie entière.`,
 l:[R`Montrons que $A_k\cap B_k=\{k\}$ par double inclusion.`,R`$A_k\cap B_k=\emptyset$ car les intervalles sont consécutifs.`,R`$A_k\cap B_k=[k-1,k+1]$.`],
 lw:R`Ils se touchent en $k$ (bornes fermées) : l'intersection est $\{k\}$, pas $\emptyset$.`,
 hint:R`$\bigcup_kA_k=[-1,+\infty[$ et $\bigcup_kB_k=[0,+\infty[$. Pour $\supset$, pose $k=E(x)+1$ (resp. $E(x)$).`,
 sol:R`$k\in A_k$ et $k\in B_k$ ; si $x\in A_k\cap B_k$, $k-1\le x\le k$ et $k\le x\le k+1$ donc $x=k$. <b>$A_k\cap B_k=\{k\}$</b>, d'où <b>$\bigcup(A_k\cap B_k)=\mathbb N$</b>.<br>$\bigcup A_k=[-1,+\infty[$ : ($\subset$) $x\in A_k$ donne $x\ge k-1\ge-1$ ; ($\supset$) pour $x\ge-1$, $k=E(x)+1\in\mathbb N$ et $k-1\le x\le k$. De même $\bigcup B_k=[0,+\infty[$ (avec $k=E(x)$).<br>Comme $\bigcup B_k\subset\bigcup A_k$ : <b>$\big(\bigcup A_k\big)\cap\big(\bigcup B_k\big)=[0,+\infty[$</b>.`,
 bar:[[0.75,'A_k ∩ B_k = {k}'],[0.25,'Union = ℕ'],[1,'∪A_k et ∪B_k par double inclusion (E(x))'],[0.5,'Intersection finale']]},
{id:'25-4d',src:'CC 2025 · Ex 4.4',pts:1.5,k:'a',
 q:R`On suppose $A_k\subset A_{k+1}$ et $B_k\subset B_{k+1}$ pour tout $k$. Montrer $\bigcup_k(A_k\cap B_k)=\big(\bigcup_kA_k\big)\cap\big(\bigcup_kB_k\big)$.`,
 m:['inc','abs','rec','ce'],mw:R`Une inclusion est déjà faite (question 2) : il reste $\supset$, avec $K=\max(k,k')$.`,
 l:[R`D'après la question 2, il suffit de montrer $\big(\bigcup A_k\big)\cap\big(\bigcup B_k\big)\subset\bigcup(A_k\cap B_k)$.`,R`Soit $x\in\big(\bigcup A_k\big)\cap\big(\bigcup B_k\big)$ : $\exists k$, $x\in A_k\cap B_k$.`,R`Par récurrence sur $k$, $A_k\cap B_k\subset A_{k+1}\cap B_{k+1}$.`],
 lw:R`Le 2ᵉ suppose un <b>même</b> $k$ pour les deux : c'est justement le piège.`,
 hint:R`$x\in A_k$ et $x\in B_{k'}$ avec $k\neq k'$ a priori. Quel indice contient les deux ?`,
 sol:R`Par la question 2, il reste $\supset$. Soit $x\in\big(\bigcup A_k\big)\cap\big(\bigcup B_k\big)$ : $\exists k$, $x\in A_k$ et $\exists k'$, $x\in B_{k'}$. Posons <b>$K=\max(k,k')$</b> : par croissance, $A_k\subset A_K$ et $B_{k'}\subset B_K$, donc $x\in A_K\cap B_K\subset\bigcup(A_k\cap B_k)$. Égalité par double inclusion.`,
 bar:[[0.25,'Recyclage de la question 2'],[0.5,'∃ k et ∃ k′ distincts'],[0.75,'K = max(k, k′) + croissance']]},
/* ---------- VARIANTES INÉDITES ---------- */
{id:'v1',src:'Variante · quantificateurs',pts:1.5,k:'v',
 q:R`Nier : $\forall\varepsilon>0,\ \exists\eta>0,\ \forall x\in\mathbb R,\ |x|<\eta\Rightarrow|f(x)|<\varepsilon$.`,
 m:['tr','ce','wit','rec'],mw:R`Mécanique : on retourne chaque quantificateur dans l'ordre, puis non$(P\Rightarrow Q)$ = $P$ et non $Q$.`,
 l:[R`$\exists\varepsilon>0,\ \forall\eta>0,\ \exists x\in\mathbb R,\ |x|<\eta$ et $|f(x)|\ge\varepsilon$`,R`$\exists\varepsilon>0,\ \forall\eta>0,\ \exists x\in\mathbb R,\ |x|\ge\eta\Rightarrow|f(x)|\ge\varepsilon$`,R`$\exists\varepsilon\le0,\ \forall\eta\le0,\ \exists x,\ |x|<\eta$ et $|f(x)|\ge\varepsilon$`],
 lw:R`On ne nie <b>jamais</b> les domaines ($\varepsilon>0$ reste $\varepsilon>0$).`,
 hint:R`Trois quantificateurs à retourner, puis une implication à nier.`,
 sol:R`$\exists\varepsilon>0,\ \forall\eta>0,\ \exists x\in\mathbb R,\ |x|<\eta$ <b>et</b> $|f(x)|\ge\varepsilon$.`,
 bar:[[0.75,'Quantificateurs retournés, domaines gardés'],[0.75,'non(⇒) = « et » + ≥']]},
{id:'v2',src:'Variante · vrai/faux',pts:1.5,k:'v',
 q:R`$P : \exists y\in\mathbb R,\ \forall x\in\mathbb R,\ y>x^2$. Vraie ou fausse ?`,
 m:['neg','wit','rec','dbl'],mw:R`Fausse (un $y$ fixe est dépassé par $x^2$) : on prouve la négation.`,
 l:[R`$\text{non}P : \forall y\in\mathbb R,\ \exists x\in\mathbb R,\ x^2\ge y$. Soit $y\in\mathbb R$.`,R`Posons $y=x^2+1$. Alors $y>x^2$.`,R`Posons $y=100$. Soit $x\in\mathbb R$.`],
 lw:R`Le 2ᵉ fait dépendre $y$ de $x$ (ce serait la version $\forall x\exists y$, vraie).`,
 hint:R`Pour un $y$ donné, prends $x=\sqrt{|y|}$.`,
 sol:R`$\text{non}P : \forall y\in\mathbb R,\ \exists x\in\mathbb R,\ x^2\ge y$. Soit $y\in\mathbb R$ ; posons $x=\sqrt{|y|}$ : $x^2=|y|\ge y$. La négation est vraie, donc <b>$P$ est fausse</b>.`,
 bar:[[0.5,'Négation'],[1,'Témoin x = √|y| + conclusion']]},
{id:'v3',src:'Variante · ensembles',pts:2,k:'v',
 q:R`Montrer que si $A\cup B=A\cap B$ alors $A=B$.`,
 m:['dbl','ce','rec','tab'],mw:R`On suppose l'hypothèse puis double inclusion.`,
 l:[R`Supposons $A\cup B=A\cap B$. Soit $x\in A$.`,R`Soit $x\in A\cup B$. Alors $x\in A$ et $x\in B$.`,R`$A\cup B=A\cap B$ donc $A=B$ par définition.`],
 hint:R`$x\in A\subset A\cup B=A\cap B\subset B$.`,
 sol:R`Supposons $A\cup B=A\cap B$. Soit $x\in A$ : $x\in A\cup B=A\cap B$, donc $x\in B$. D'où $A\subset B$. Par symétrie, $B\subset A$. Donc $A=B$ par double inclusion.`,
 bar:[[0.5,'On suppose + annonce'],[1,'A ⊂ B'],[0.5,'B ⊂ A (symétrie)']]},
{id:'v4',src:'Variante · ensembles',pts:1.5,k:'v',
 q:R`Montrer $(A\setminus B)\setminus C=A\setminus(B\cup C)$.`,
 m:['eqv','abs','ce','rec'],mw:R`Chaîne d'équivalences + De Morgan.`,
 l:[R`$x\in(A\setminus B)\setminus C\iff(x\in A$ et $x\notin B)$ et $x\notin C$`,R`$x\in(A\setminus B)\setminus C\iff x\in A$ et $(x\notin B$ ou $x\notin C)$`,R`Soit $x\in A$. Alors $x\notin B\cup C$.`],
 hint:R`$x\notin B$ et $x\notin C$ $\iff$ non($x\in B$ ou $x\in C$).`,
 sol:R`$x\in(A\setminus B)\setminus C\iff x\in A$ et $x\notin B$ et $x\notin C\iff x\in A$ et non($x\in B$ ou $x\in C$) $\iff x\in A$ et $x\notin B\cup C\iff x\in A\setminus(B\cup C)$.`,
 bar:[[0.5,'Traduction'],[0.5,'De Morgan'],[0.5,'Conclusion']]},
{id:'v5',src:'Variante · produit cartésien',pts:2,k:'v',
 q:R`Montrer $(A\times B)\cap(C\times D)=(A\cap C)\times(B\cap D)$.`,
 m:['eqv','ce','abs','rec'],mw:R`Chaîne d'équivalences sur un couple $(x,y)$.`,
 l:[R`$(x,y)\in(A\times B)\cap(C\times D)\iff(x\in A$ et $y\in B)$ et $(x\in C$ et $y\in D)$`,R`$(x,y)\in(A\times B)\cap(C\times D)\iff(x\in A$ ou $x\in C)$ et $(y\in B$ ou $y\in D)$`,R`Soit $x\in A\cap C$.`],
 hint:R`Réordonne les 4 « et » (commutativité).`,
 sol:R`$(x,y)\in(A\times B)\cap(C\times D)\iff x\in A$ et $y\in B$ et $x\in C$ et $y\in D\iff(x\in A\cap C)$ et $(y\in B\cap D)\iff(x,y)\in(A\cap C)\times(B\cap D)$.`,
 bar:[[1,'Traduction des deux appartenances'],[1,'Regroupement + conclusion']]},
{id:'v6',src:'Variante · familles indexées',pts:2,k:'v',
 q:R`$A_k=[0,k]$, $k\in\mathbb N$. Déterminer $\bigcap_{k\in\mathbb N}A_k$ et $\bigcup_{k\in\mathbb N}A_k$.`,
 m:['calc','rec','ce','abs'],mw:R`Famille croissante : $\bigcap=A_0$, $\bigcup=[0,+\infty[$.`,
 l:[R`Pour tout $k$, $A_k\subset A_{k+1}$, donc $\bigcap_kA_k=A_0=\{0\}$.`,R`$\bigcap_kA_k=\emptyset$.`,R`$\bigcap_kA_k=[0,1]$.`],
 lw:R`$k=0$ est dans $\mathbb N$ : $A_0=[0,0]=\{0\}$.`,
 hint:R`Que vaut $A_0$ ? Pour l'union, pense à $E(x)+1$.`,
 sol:R`Emboîtement donc <b>$\bigcap A_k=A_0=\{0\}$</b>.<br><b>$\bigcup A_k=[0,+\infty[$</b> : ($\subset$) $x\in[0,k]$ donne $x\ge0$. ($\supset$) Soit $x\ge0$, $k=E(x)+1\in\mathbb N$ et $0\le x<k$, donc $x\in A_k$.`,
 bar:[[0.75,'Intersection = {0}'],[1.25,'Union par double inclusion']]},
{id:'v7',src:'Variante · familles indexées',pts:2,k:'v',
 q:R`$A_n=\left]-\frac1n,\frac1n\right[$, $n\in\mathbb N^*$. Déterminer $\bigcap_{n\in\mathbb N^*}A_n$.`,
 m:['calc','ce','rec','wit'],mw:R`On devine $\{0\}$, puis double inclusion. Pour $x\neq0$, un $n$ qui l'exclut.`,
 l:[R`Montrons que $\bigcap A_n=\{0\}$ par double inclusion. Pour tout $n$, $0\in A_n$.`,R`$\bigcap A_n=\emptyset$ car $\frac1n\to0$.`,R`$\bigcap A_n=A_1$ car la famille est décroissante.`],
 lw:R`Décroissante : $\bigcap$ est la « limite », c'est $\bigcup$ qui vaut $A_1$. Et $0$ est dans tous les $A_n$ !`,
 hint:R`Si $x\neq0$, prends $n>\frac1{|x|}$.`,
 sol:R`$0\in A_n$ pour tout $n$ donc $\{0\}\subset\bigcap A_n$. Soit $x\neq0$ : posons $n=E\big(\tfrac1{|x|}\big)+1$, alors $n>\frac1{|x|}$ donc $|x|>\frac1n$, $x\notin A_n$, donc $x\notin\bigcap A_n$. Par contraposée, $\bigcap A_n\subset\{0\}$. <b>$\bigcap A_n=\{0\}$</b>.`,
 bar:[[0.5,'0 dans tous les A_n'],[1.5,'x ≠ 0 exclu avec n explicite']]},
{id:'v8',src:'Variante · implication',pts:1.5,k:'v',
 q:R`$n\in\mathbb Z$. Montrer : si $n^2$ est pair, alors $n$ est pair.`,
 m:['ctp','dir','ce','rec'],mw:R`En direct, on ne sait pas exploiter « $n^2$ pair ». La contraposée donne $n=2k+1$, facile.`,
 l:[R`Raisonnons par contraposée : supposons $n$ impair, soit $n=2k+1$ avec $k\in\mathbb Z$.`,R`Supposons $n^2$ pair : $n^2=2k$, donc $n=\sqrt{2k}$.`,R`Supposons $n$ pair. Alors $n^2$ est pair.`],
 lw:R`Le 3ᵉ démontre la <b>réciproque</b>.`,
 hint:R`Développe $(2k+1)^2$.`,
 sol:R`Par contraposée : supposons $n$ impair, $n=2k+1$. Alors $n^2=4k^2+4k+1=2(2k^2+2k)+1$ est impair. Donc $n^2$ pair $\Rightarrow n$ pair.`,
 bar:[[0.5,'Annonce contraposée correcte'],[1,'Calcul + conclusion']]},
{id:'v9',src:'Variante · implication',pts:1.5,k:'v',
 q:R`$x\in\mathbb R$. Montrer : si $\forall\varepsilon>0,\ |x|\le\varepsilon$, alors $x=0$.`,
 m:['abs','dir','wit','rec'],mw:R`Par l'absurde (ou contraposée) : si $x\neq0$, on choisit un $\varepsilon$ qui coince.`,
 l:[R`Supposons $\forall\varepsilon>0,\ |x|\le\varepsilon$ et, par l'absurde, $x\neq0$. Posons $\varepsilon=\frac{|x|}2$.`,R`Soit $\varepsilon>0$. Alors $|x|\le\varepsilon$, donc $x=0$.`,R`Posons $\varepsilon=1$ : $|x|\le1$.`],
 hint:R`Applique l'hypothèse avec $\varepsilon=|x|/2>0$.`,
 sol:R`Par l'absurde, $x\neq0$. Alors $\varepsilon=\frac{|x|}2>0$, et l'hypothèse donne $|x|\le\frac{|x|}2$, soit $|x|\le0$, donc $x=0$ : contradiction. Donc $x=0$.`,
 bar:[[0.5,'Annonce absurde'],[1,'ε = |x|/2 + contradiction']]},
{id:'v10',src:'Variante · contraposée',pts:1.5,k:'v',
 q:R`$a,b\in\mathbb R$. Écrire la contraposée de : « si $a+b\notin\mathbb Q$, alors $a\notin\mathbb Q$ ou $b\notin\mathbb Q$ », puis la démontrer.`,
 m:['ctp','ce','dir','rec'],mw:R`La contraposée (« $a,b$ rationnels ⇒ $a+b$ rationnel ») est évidente : on démontre celle-là.`,
 l:[R`Contraposée : si $a\in\mathbb Q$ et $b\in\mathbb Q$, alors $a+b\in\mathbb Q$.`,R`Contraposée : si $a\in\mathbb Q$ ou $b\in\mathbb Q$, alors $a+b\in\mathbb Q$.`,R`Contraposée : si $a+b\in\mathbb Q$, alors $a\in\mathbb Q$ et $b\in\mathbb Q$.`],
 lw:R`non($a\notin\mathbb Q$ ou $b\notin\mathbb Q$) = $a\in\mathbb Q$ <b>et</b> $b\in\mathbb Q$ (De Morgan). Le 3ᵉ est l'inverse.`,
 hint:R`$\frac pq+\frac rs=\frac{ps+rq}{qs}$.`,
 sol:R`Contraposée : si $a\in\mathbb Q$ et $b\in\mathbb Q$ alors $a+b\in\mathbb Q$. Preuve : $a=\frac pq$, $b=\frac rs$ ($q,s\neq0$), donc $a+b=\frac{ps+rq}{qs}\in\mathbb Q$.`,
 bar:[[0.75,'Contraposée (De Morgan)'],[0.75,'Preuve']]},
{id:'v11',src:'Variante · réciproque',pts:2,k:'v',
 q:R`Montrer $A\subset B\Rightarrow A\cap C\subset B\cap C$. La réciproque est-elle vraie ?`,
 m:['inc','dbl','abs','rec'],mw:R`Inclusion simple, puis contre-exemple (penser à $C=\emptyset$).`,
 l:[R`Supposons $A\subset B$. Soit $x\in A\cap C$ : $x\in A$ et $x\in C$.`,R`Supposons $A\subset B$. Soit $x\in A\cap C$ : $x\in A$ ou $x\in C$.`,R`Supposons $A\cap C\subset B\cap C$. Soit $x\in A$.`],
 hint:R`Avec $C=\emptyset$, l'hypothèse de la réciproque est toujours vraie.`,
 sol:R`Supposons $A\subset B$. Soit $x\in A\cap C$ : $x\in A\subset B$ et $x\in C$, donc $x\in B\cap C$.<br>Réciproque : $A\cap C\subset B\cap C\Rightarrow A\subset B$. <b>Fausse</b> : $A=\{1\}$, $B=\emptyset$, $C=\emptyset$ : $A\cap C=\emptyset\subset\emptyset$ mais $A\not\subset B$.`,
 bar:[[1,'Implication'],[0.5,'Énoncé réciproque'],[0.5,'Contre-exemple']]},
{id:'v12',src:'Variante · « pour tout y, il existe x »',pts:1.5,k:'v',
 q:R`$f(x)=x^2-1$, $E=\mathbb R$, $F=[-1,+\infty[$. « $\forall y\in F,\ \exists x\in E,\ y=f(x)$ » est-elle vraie ?`,
 m:['wit','ce','neg','rec'],mw:R`Soit $y$, on résout, on pose $x$, on vérifie.`,
 l:[R`Soit $y\ge-1$. Posons $x=\sqrt{y+1}$, bien défini car $y+1\ge0$.`,R`Prenons $y=-2$ : pas de solution.`,R`Soit $x\in\mathbb R$, $f(x)\ge-1$.`],
 lw:R`$-2\notin F$ : pas un contre-exemple valable ici.`,
 hint:R`La racine existe-t-elle ? Est-elle dans $E$ ?`,
 sol:R`Soit $y\in[-1,+\infty[$. Posons $x=\sqrt{y+1}$ (défini car $y+1\ge0$), $x\in\mathbb R=E$, et $f(x)=y+1-1=y$. <b>Vraie.</b>`,
 bar:[[0.5,'Soit y'],[0.5,'x explicite, bien défini'],[0.5,'f(x) = y']]},
{id:'v13',src:'Variante · disjonction de cas',pts:2,k:'v',
 q:R`Montrer que $\forall x\in\mathbb R,\ |x-1|\le x^2-x+1$.`,
 m:['cas','ce','rec','abs'],mw:R`La valeur absolue force deux cas : $x\ge1$ et $x<1$.`,
 l:[R`Soit $x\in\mathbb R$. Si $x\ge1$, $|x-1|=x-1$ ; si $x<1$, $|x-1|=1-x$.`,R`Prenons $x=0$ : $1\le1$.`,R`$|x-1|=x-1$, donc on montre $x-1\le x^2-x+1$.`],
 lw:R`Un exemple ne prouve pas un $\forall$. Et $|x-1|=x-1$ seulement si $x\ge1$.`,
 hint:R`Cas $x\ge1$ : $(x^2-x+1)-(x-1)=(x-1)^2+1$. Cas $x<1$ : la différence vaut $x^2$.`,
 sol:R`Soit $x\in\mathbb R$.<br>Si $x\ge1$ : $(x^2-x+1)-(x-1)=x^2-2x+2=(x-1)^2+1\ge0$.<br>Si $x<1$ : $(x^2-x+1)-(1-x)=x^2\ge0$.<br>Dans tous les cas, $|x-1|\le x^2-x+1$.`,
 bar:[[0.5,'Soit x + deux cas'],[0.75,'Cas x ≥ 1'],[0.75,'Cas x < 1 + « dans tous les cas »']]}
];

/* ============ ONGLET 4 : RADAR À PIÈGES ============ */
var vf=[
 {s:R`$\text{non}(\forall x\,\exists y,\ P(x,y))\equiv\exists x\,\forall y,\ \text{non}P(x,y)$`,a:1,e:R`On retourne chaque quantificateur sans changer l'ordre.`},
 {s:R`La négation de « $P\Rightarrow Q$ » est « non $P\Rightarrow$ non $Q$ ».`,a:0,e:R`C'est « $P$ <b>et</b> non $Q$ ». (« non $P\Rightarrow$ non $Q$ » est l'inverse.)`},
 {s:R`La contraposée de $P\Rightarrow Q$ est $Q\Rightarrow P$.`,a:0,e:R`$Q\Rightarrow P$ est la <b>réciproque</b>. Contraposée : non $Q\Rightarrow$ non $P$.`},
 {s:R`Une implication et sa réciproque ont toujours la même valeur de vérité.`,a:0,e:R`Aucun lien (CC 2023 Ex1 : $P$ vraie, réciproque fausse). C'est la <b>contraposée</b> qui a même valeur.`},
 {s:R`$(\exists x\,\forall y,\ R)\Rightarrow(\forall y\,\exists x,\ R)$`,a:1,e:R`Un $x$ qui marche pour tous les $y$ marche en particulier pour chacun.`},
 {s:R`$(\forall x\,\exists y,\ R)\Rightarrow(\exists y\,\forall x,\ R)$`,a:0,e:R`« Chacun a une mère » n'entraîne pas « une mère de tout le monde ».`},
 {s:R`$\text{non}(x>0\text{ et }y>0)\equiv(x\le0\text{ et }y\le0)$`,a:0,e:R`De Morgan : « et » devient « <b>ou</b> » : $x\le0$ ou $y\le0$.`},
 {s:R`$\text{non}(0\le x\le1)\equiv(x<0\text{ ou }x>1)$`,a:1,e:R`$0\le x\le1$, c'est « $0\le x$ et $x\le1$ ».`},
 {s:R`La négation de « $x+y>0$ » est « $x+y<0$ ».`,a:0,e:R`C'est $x+y\le0$. Erreur classique qui coûte la ligne entière.`},
 {s:R`$\bigcap_{n\ge1}\left]-\frac1n,\frac1n\right[=\emptyset$`,a:0,e:R`$0$ est dans tous : l'intersection vaut $\{0\}$.`},
 {s:R`$\bigcup_{n\in\mathbb N^*}\{-n,n\}=\mathbb Z$`,a:0,e:R`$0$ manque, car $n\ge1$ (CC 2024 Ex4.1).`},
 {s:R`$]-2,2[\,\setminus\,]-1,1[\,=\,]-2,-1]\cap[1,2[$ (comme dans le corrigé 2024)`,a:0,e:R`Coquille du corrigé : c'est $\cup$. Avec $\cap$ on obtiendrait $\emptyset$.`},
 {s:R`Si $D=\emptyset$, alors $P_1(C\times D)=C$.`,a:0,e:R`$C\times\emptyset=\emptyset$ donc $P_1=\emptyset$. C'est pour ça que l'énoncé dit « non vides ».`},
 {s:R`$A\times B=B\times A$`,a:0,e:R`Couples ordonnés : $(1,7)\neq(7,1)$.`},
 {s:R`Pour prouver $\forall x\in\mathbb R,\ P(x)$, vérifier $x=0,1,2$ suffit.`,a:0,e:R`Il faut « Soit $x\in\mathbb R$ » quelconque.`},
 {s:R`Un seul contre-exemple suffit pour montrer qu'un énoncé « $\forall$ » est faux.`,a:1,e:R`La négation est un $\exists$ : un témoin suffit.`},
 {s:R`Un seul exemple suffit pour démontrer un énoncé « $\exists$ ».`,a:1,e:R`C'est exactement « exhiber un témoin ».`},
 {s:R`$C_E(A\cap B)=C_E(A)\cap C_E(B)$`,a:0,e:R`Le complémentaire échange $\cap$ et $\cup$ : $C_E(A)\cup C_E(B)$.`},
 {s:R`$A\setminus B=A\cap C_E(B)$`,a:1,e:R`Dans $A$ et pas dans $B$.`},
 {s:R`Si $A_k\subset A_{k+1}$ pour tout $k\in\mathbb N$, alors $\bigcap_k A_k=A_0$.`,a:1,e:R`Poupées russes : la plus petite est $A_0$.`},
 {s:R`Négation de « $\forall(a,b)\in E^2,\ f(a)=f(b)\Rightarrow a=b$ » : « $\exists(a,b)\in E^2,\ f(a)=f(b)$ et $a\neq b$ ».`,a:1,e:R`$\forall$ devient $\exists$, $(P\Rightarrow Q)$ devient ($P$ et non $Q$). Le corrigé oublie le carré de $E^2$ : garde-le.`},
 {s:R`Négation de « $\exists p\in\mathcal P,\ n<p<2n$ » : « $\forall p\in\mathcal P,\ p<n$ ou $p>2n$ ».`,a:0,e:R`non($n<p$) = $p\le n$ : c'est $p\le n$ ou $p\ge2n$.`},
 {s:R`Dans « $\exists x\,\forall y,\ x+y>0$ », $x$ peut dépendre de $y$.`,a:0,e:R`$x$ est choisi <b>avant</b> $y$ : il est fixe.`},
 {s:R`Contraposée de « $a\neq0\Rightarrow\exists\varepsilon>0,\ |a|\ge\varepsilon$ » : « $(\forall\varepsilon>0,\ |a|<\varepsilon)\Rightarrow a=0$ ».`,a:1,e:R`Exactement le corrigé 2025 Ex2.3.`},
 {s:R`Pour tous réels $a,b$ : $a^2=b^2\Rightarrow a=b$.`,a:0,e:R`$(-1)^2=1^2$. Il faut $a,b\ge0$ : c'est la clé de CC 2024 Ex2.1c.`},
 {s:R`En maths, « $P$ ou $Q$ » exclut le cas où $P$ et $Q$ sont vraies.`,a:0,e:R`Le « ou » est <b>inclusif</b>.`},
 {s:R`Si $A\cup C\subset B\cup C$, alors $A\subset B$.`,a:0,e:R`$A=\{1\}$, $B=\emptyset$, $C=\{1\}$ (réciproque de CC 2023 Ex3.2).`},
 {s:R`Si $P$ est fausse, alors $P\Rightarrow Q$ est vraie.`,a:1,e:R`Une promesse conditionnelle n'est rompue que si la condition est remplie.`},
 {s:R`$\big(\bigcup_kA_k\big)\cap\big(\bigcup_kB_k\big)\subset\bigcup_k(A_k\cap B_k)$ est toujours vrai.`,a:0,e:R`Faux en général ($A_0=\{1\},B_1=\{1\}$, le reste vide). Il faut la croissance (CC 2025 Ex4.4).`},
 {s:R`$C_E(C_E(A))=A$`,a:1,e:R`Réflexe utile en CC 2024 Ex3.2.`}
];

var err=[
 {t:R`Nier $B : \forall x\in\mathbb R,\ \exists y\in\mathbb R,\ x+y>0$`,L:[R`On échange les quantificateurs en gardant l'ordre.`,R`$\text{non}B : \exists x\in\mathbb R,\ \forall y\in\mathbb R,\ x+y<0$.`],w:1,e:R`non($>$) c'est $\le$, pas $<$.`},
 {t:R`Montrer $A\subset B\Rightarrow A\cup C\subset B\cup C$`,L:[R`On suppose $A\subset B$.`,R`Soit $x\in A\cup C$. Alors $x\in A$ et $x\in C$.`,R`Donc $x\in B$ et $x\in C$.`,R`Donc $x\in B\cup C$.`],w:1,e:R`$x\in A\cup C$ veut dire $x\in A$ <b>ou</b> $x\in C$.`},
 {t:R`Montrer $\forall x\in\mathbb R,\ \exists y\in\mathbb R,\ y>x^2$`,L:[R`Soit $x\in\mathbb R$.`,R`Posons $y=5$.`,R`Alors $y>x^2$, d'où l'existence.`],w:1,e:R`$y=5$ échoue pour $x=3$. $y$ doit dépendre de $x$ : $y=x^2+1$.`},
 {t:R`Montrer $\exists x\in\mathbb R,\ \forall y\in\mathbb R,\ y^2>x$`,L:[R`Soit $y\in\mathbb R$.`,R`Posons $x=y^2-1$.`,R`Alors $y^2>x$.`],w:1,e:R`Ici $x$ dépend de $y$ : c'est l'ordre $\forall y\exists x$. Il faut fixer $x=-1$ d'abord, puis « soit $y$ ».`},
 {t:R`Sur $E=[1,+\infty[$ : $f(a)=f(b)\Rightarrow a=b$ avec $f(x)=x^2-1$`,L:[R`Soit $(a,b)\in E^2$ avec $f(a)=f(b)$.`,R`Alors $a^2-1=b^2-1$, donc $a^2=b^2$.`,R`Donc $a=b$.`],w:2,e:R`Il manque « <b>car $a>0$ et $b>0$</b> » : sans ça, $a=-b$ est possible. Ligne sanctionnée.`},
 {t:R`Montrer $A=B$`,L:[R`Soit $x\in A$. … Donc $x\in B$.`,R`Ainsi $A\subset B$.`,R`D'où $A=B$.`],w:2,e:R`Une seule inclusion : il manque $B\subset A$. Moitié des points perdue.`},
 {t:R`Énoncer la réciproque de « si $ac<0$ alors $\Delta>0$ »`,L:[R`La réciproque est :`,R`« si $\Delta\le0$ alors $ac\ge0$ ».`],w:1,e:R`Ça, c'est la <b>contraposée</b>. Réciproque : « si $\Delta>0$ alors $ac<0$ ».`},
 {t:R`Montrer $\bigcup_{n\in\mathbb N^*}]-n,n[\,=\mathbb R$, inclusion $\supset$`,L:[R`Soit $x\in\mathbb R$.`,R`Alors $x\in\,]-n,n[$.`,R`Donc $x\in\bigcup_nA_n$.`],w:1,e:R`Quel $n$ ? Il faut l'exhiber : $n=E(|x|)+1\in\mathbb N^*$, et alors $|x|<n$.`},
 {t:R`Familles croissantes : $\big(\bigcup A_k\big)\cap\big(\bigcup B_k\big)\subset\bigcup(A_k\cap B_k)$`,L:[R`Soit $x$ à gauche : $\exists k$, $x\in A_k$ et $\exists k'$, $x\in B_{k'}$.`,R`Donc $x\in A_k\cap B_k$.`,R`Donc $x\in\bigcup_k(A_k\cap B_k)$.`],w:1,e:R`$k\neq k'$ a priori ! Il faut $K=\max(k,k')$ et la croissance.`},
 {t:R`Négation de « $a\neq0\Rightarrow\exists\varepsilon>0,\ |a|\ge\varepsilon$ »`,L:[R`On nie l'implication :`,R`$a=0\Rightarrow\forall\varepsilon>0,\ |a|<\varepsilon$.`],w:1,e:R`La négation d'une implication n'est pas une implication : $a\neq0$ <b>et</b> $\forall\varepsilon>0,\ |a|<\varepsilon$.`},
 {t:R`Par l'absurde : montrer $C\setminus A=\emptyset$`,L:[R`Supposons $C\setminus A\neq\emptyset$.`,R`Soit $x\in C\setminus A$ : $x\in C$ et $x\in A$.`,R`…`],w:1,e:R`$x\in C\setminus A$ : $x\in C$ et $x\notin A$.`},
 {t:R`Montrer $C\subset P_1(C\times D)$ ($C$, $D$ non vides)`,L:[R`Soit $x\in C$.`,R`Prenons $y\in D$ (c'est toujours possible).`,R`Alors $(x,y)\in C\times D$, donc $x\in P_1(C\times D)$.`],w:1,e:R`« Toujours possible » est faux : on prend $y$ <b>car $D$ est non vide</b>. C'est le mot qui rapporte le point.`},
 {t:R`Montrer que $Q : \exists y,\ \forall x,\ y^2\neq x$ est fausse`,L:[R`Prenons $y=0$ et $x=0$.`,R`Alors $y^2=x$.`,R`Donc $Q$ est fausse.`],w:0,e:R`Un seul $y$ testé ne réfute pas un $\exists$ : il faut montrer que <b>tout</b> $y$ échoue (soit $y$, posons $x=y^2$).`},
 {t:R`Montrer $A\cap B=\emptyset\Rightarrow B\subset C_E(A)$`,L:[R`On suppose $A\cap B=\emptyset$.`,R`Soit $x\in C_E(A)$.`,R`Alors $x\notin A$ donc $x\in B$.`],w:1,e:R`On part du mauvais ensemble : pour $B\subset C_E(A)$, on prend $x\in B$.`}
];

